import React, { useState } from 'react';
import { 
  Table, 
  Card,
  Row,
  Col,
  Select,
  DatePicker,
  Button,
  Space,
  Tag,
  Input,
  message
} from 'antd';
import { ReloadOutlined, ExportOutlined } from '@ant-design/icons';
import { useGetOperationLogsQuery } from '@/store/api/logApi';
import { OPERATION_LOG_ACTIONS } from '@/constants';
import type { ColumnsType } from 'antd/es/table';
import type { OperationLog } from '@/types';

const { RangePicker } = DatePicker;
const { Search } = Input;
const { Option } = Select;

const OperationLogList: React.FC = () => {
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const [searchKeyword, setSearchKeyword] = useState('');
  const [selectedAction, setSelectedAction] = useState<string>('');
  const [dateRange, setDateRange] = useState<any>(null);

  const { data, isLoading, refetch } = useGetOperationLogsQuery({
    page,
    pageSize,
    action: selectedAction,
    startDate: dateRange?.[0]?.format('YYYY-MM-DD'),
    endDate: dateRange?.[1]?.format('YYYY-MM-DD'),
  });

  const handleExport = () => {
    message.info('导出功能开发中');
  };

  const getActionColor = (action: string) => {
    const colorMap: Record<string, string> = {
      CREATE_USER: 'green',
      UPDATE_USER: 'blue',
      DELETE_USER: 'red',
      CREATE_ROLE: 'green',
      UPDATE_ROLE: 'blue',
      DELETE_ROLE: 'red',
      LOGIN: 'cyan',
      LOGOUT: 'orange',
    };
    return colorMap[action] || 'default';
  };

  const getActionLabel = (action: string) => {
    const labelMap: Record<string, string> = {
      CREATE_USER: '创建用户',
      UPDATE_USER: '更新用户',
      DELETE_USER: '删除用户',
      CREATE_ROLE: '创建角色',
      UPDATE_ROLE: '更新角色',
      DELETE_ROLE: '删除角色',
      LOGIN: '登录',
      LOGOUT: '登出',
    };
    return labelMap[action] || action;
  };

  const columns: ColumnsType<OperationLog> = [
    {
      title: '操作人',
      dataIndex: 'userName',
      key: 'userName',
      width: 120,
    },
    {
      title: '操作',
      dataIndex: 'action',
      key: 'action',
      width: 120,
      render: (action: string) => (
        <Tag color={getActionColor(action)}>
          {getActionLabel(action)}
        </Tag>
      ),
    },
    {
      title: '资源',
      dataIndex: 'resource',
      key: 'resource',
      width: 100,
      render: (resource: string) => <Tag color="blue">{resource}</Tag>,
    },
    {
      title: '详情',
      dataIndex: 'details',
      key: 'details',
      ellipsis: true,
      render: (details: any) => (
        <div style={{ maxWidth: 300 }}>
          {details ? JSON.stringify(details) : '-'}
        </div>
      ),
    },
    {
      title: 'IP地址',
      dataIndex: 'ip',
      key: 'ip',
      width: 120,
    },
    {
      title: '操作时间',
      dataIndex: 'timestamp',
      key: 'timestamp',
      width: 180,
      render: (date: string) => new Date(date).toLocaleString('zh-CN'),
    },
  ];

  return (
    <div className="operation-log-list-page">
      <Card>
        <Row gutter={16} style={{ marginBottom: 16 }}>
          <Col span={6}>
            <Search
              placeholder="搜索操作人"
              allowClear
              enterButton
              value={searchKeyword}
              onChange={(e) => setSearchKeyword(e.target.value)}
              onSearch={setSearchKeyword}
            />
          </Col>
          <Col span={6}>
            <Select
              placeholder="选择操作类型"
              allowClear
              style={{ width: '100%' }}
              value={selectedAction}
              onChange={setSelectedAction}
            >
              {Object.entries(OPERATION_LOG_ACTIONS).map(([key, value]) => (
                <Option key={value} value={value}>
                  {getActionLabel(value)}
                </Option>
              ))}
            </Select>
          </Col>
          <Col span={6}>
            <RangePicker
              style={{ width: '100%' }}
              value={dateRange}
              onChange={setDateRange}
            />
          </Col>
          <Col span={6} style={{ textAlign: 'right' }}>
            <Space>
              <Button icon={<ReloadOutlined />} onClick={() => refetch()}>刷新</Button>
              <Button icon={<ExportOutlined />} onClick={handleExport}>导出</Button>
            </Space>
          </Col>
        </Row>

        <Table
          rowKey="id"
          columns={columns}
          dataSource={data?.data || []}
          loading={isLoading}
          pagination={{
            current: page,
            pageSize: pageSize,
            total: data?.pagination.total || 0,
            showSizeChanger: true,
            showQuickJumper: true,
            showTotal: (total) => `共 ${total} 条`,
          }}
          onChange={(pagination) => {
            setPage(pagination.current || 1);
            setPageSize(pagination.pageSize || 20);
          }}
        />
      </Card>
    </div>
  );
};

export default OperationLogList;